    template <bool HasMaximum> static void check(T value, [[maybe_unused]] T maximum) {
#ifndef SKIP_RUNTIME_CHECKS
        if constexpr (HasMaximum) {
            if (value > maximum) throw std::out_of_range("RadixSort: value exceeds maximum");
        }
#else
        (void)value;
#endif
    }
