// SPDX-License-Identifier: CC0-1.0
// 巨大入力を偽装せず、内部カウンタ2経路と最大値付近の累積和を補足する。
#ifndef SIRKIT_RADIX_SOURCE
#define SIRKIT_RADIX_SOURCE "../../../Algorithm/Radix_sort.cpp"
#endif
#include SIRKIT_RADIX_SOURCE
#include <algorithm>
#include <array>
#include <bit>
#include <concepts>
#include <cstddef>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <limits>
#include <numeric>
#include <random>
#include <stdexcept>
#include <type_traits>
#include <utility>
#include <vector>

namespace {
std::size_t checks = 0, input_cases = 0, kernel_calls = 0, prefix_cases = 0;
}
static void require_impl(bool ok, const char* expression, int line) {
    ++checks;
    if (!ok) {
        std::fprintf(stderr, "line %d: %s (%ju checks)\n", line, expression,
                     static_cast<std::uintmax_t>(checks));
        std::abort();
    }
}
#define SIRKIT_TEST_REQUIRE(ok) require_impl(bool(ok), #ok, __LINE__)

template<class T, class Counter>
static void inspect_kernel(const std::vector<T>& input, const std::vector<T>& expected,
                           const std::vector<std::size_t>& expected_order) {
    using Detail = reinsirk::detail::RadixSortDetail<T, Counter>;
    static_assert(std::is_unsigned_v<Counter>);
    static_assert(std::same_as<decltype(Detail::order(input)), std::vector<std::size_t>>);
    std::vector<T> scratch;
    for (bool maximum : {false, true}) {
        auto actual = input;
        actual.reserve(input.size() + 17);
        const auto* address = actual.data();
        const auto capacity = actual.capacity();
        if (maximum)
            Detail::template sort<true>(actual, scratch, std::numeric_limits<T>::max());
        else Detail::template sort<false>(actual, scratch, T{});
        ++kernel_calls;
        SIRKIT_TEST_REQUIRE(actual == expected);
        SIRKIT_TEST_REQUIRE(actual.data() == address && actual.capacity() == capacity);
    }
    const auto order = Detail::order(input);
    ++kernel_calls;
    SIRKIT_TEST_REQUIRE(order == expected_order);
}

template<class T> static void inspect_input(const std::vector<T>& input) {
    ++input_cases;
    const auto saved = input;
    auto expected = input;
    std::stable_sort(expected.begin(), expected.end());
