template<class T> static std::vector<T> make_input(std::size_t n, int kind) {
    using U = std::make_unsigned_t<T>;
    std::mt19937_64 generator(761279 + n);
    std::vector<T> input(n);
    for (std::size_t i = 0; i < n; ++i) {
        U bits = static_cast<U>(generator());
        if (kind == 1 || kind == 2 || kind == 3) bits &= U{15};
        input[i] = std::bit_cast<T>(bits);
    }
    if (kind == 2) std::sort(input.begin(), input.end());
    if (kind == 3) std::sort(input.rbegin(), input.rend());
    if (kind == 4) std::fill(input.begin(), input.end(), T{7});
    if (kind == 5) {
        for (std::size_t i = 0; i < n; ++i)
            input[i] = i % 2 ? std::numeric_limits<T>::max() : std::numeric_limits<T>::lowest();
    }
    return input;
}

template<class T, class Counter> static void invalid_maximum() {
