    using Detail = reinsirk::detail::RadixSortDetail<T, Counter>;
    const T maximum = std::is_signed_v<T> ? T(-1) : T(1);
    const T valid = std::is_signed_v<T> ? T(-7) : T(0);
    const T invalid = T(maximum + 1);
    std::vector<T> scratch;
    for (std::size_t n : {std::size_t{1}, std::size_t{64}, std::size_t{65},
                          std::size_t{129}, std::size_t{4097}}) {
        for (std::size_t position : {std::size_t{0}, n / 2, n - 1}) {
            std::vector<T> actual(n, valid);
            actual[position] = invalid;
            auto expected = actual;
            std::sort(expected.begin(), expected.end());
            const auto* address = actual.data();
            const auto capacity = actual.capacity();
            bool rejected = false;
            try { Detail::template sort<true>(actual, scratch, maximum); }
            catch (const std::out_of_range&) { rejected = true; }
            ++kernel_calls;
            SIRKIT_TEST_REQUIRE(rejected);
            SIRKIT_TEST_REQUIRE(actual.data() == address && actual.capacity() == capacity);
            std::sort(actual.begin(), actual.end());
            SIRKIT_TEST_REQUIRE(actual == expected);
        }
    }
#endif
}

template<class T> static void inspect_type() {
    for (std::size_t n : {std::size_t{0}, std::size_t{1}, std::size_t{2},
                          std::size_t{63}, std::size_t{64}, std::size_t{65},
                          std::size_t{127}, std::size_t{128}, std::size_t{129},
                          std::size_t{257}, std::size_t{4097}})
        for (int kind = 0; kind < 6; ++kind) inspect_input(make_input<T>(n, kind));
    for (int kind : {0, 1, 3}) inspect_input(make_input<T>(65537, kind));
    invalid_maximum<T, std::uint32_t>();
    invalid_maximum<T, std::size_t>();
}

template<class Counter> static void inspect_prefix(const std::array<Counter, 256>& frequencies) {
    using Detail = reinsirk::detail::RadixSortDetail<std::uint32_t, Counter>;
    static_assert(std::numeric_limits<std::uintmax_t>::digits >=
                  std::numeric_limits<Counter>::digits);
    ++prefix_cases;
    std::uintmax_t total = 0;
    for (Counter frequency : frequencies) {
        SIRKIT_TEST_REQUIRE(frequency <= std::numeric_limits<Counter>::max() - total);
        total += frequency;
    }
    auto actual = frequencies;
    Detail::prefix(actual);
    for (std::size_t i = 0; i < frequencies.size(); ++i) {
        const auto expected = std::accumulate(frequencies.begin(), frequencies.begin() + i,
                                              std::uintmax_t{0});
        SIRKIT_TEST_REQUIRE(actual[i] == expected);
        const auto end = std::uintmax_t(actual[i]) + frequencies[i];
        SIRKIT_TEST_REQUIRE(end <= total);
    }
    SIRKIT_TEST_REQUIRE(std::uintmax_t(actual.back()) + frequencies.back() == total);
    if (frequencies.back() == Counter{1} && total == std::numeric_limits<Counter>::max()) {
        // 最後の1回の散布後にoffsetが最大値へ到達しても、桁あふれしない。
        Counter offset = actual.back();
        SIRKIT_TEST_REQUIRE(offset++ == std::numeric_limits<Counter>::max() - Counter{1});
        SIRKIT_TEST_REQUIRE(offset == std::numeric_limits<Counter>::max());
    }
}

template<class Counter> static void prefix_boundaries() {
    constexpr Counter maximum = std::numeric_limits<Counter>::max();
    std::array<Counter, 256> frequencies{};
    inspect_prefix(frequencies);
    frequencies[0] = maximum;
    inspect_prefix(frequencies);
    frequencies = {};
    frequencies[255] = maximum;
    inspect_prefix(frequencies);
    frequencies = {};
    frequencies[0] = maximum - Counter{1};
    frequencies[255] = 1;
    inspect_prefix(frequencies);
    frequencies = {};
    frequencies[17] = maximum / Counter{2} + Counter{1};
    frequencies[255] = maximum - frequencies[17];
    inspect_prefix(frequencies);
    std::mt19937_64 generator(248277);
    Counter small_total = 0;
    for (auto& frequency : frequencies) {
        frequency = static_cast<Counter>(generator() % 101);
        small_total += frequency;
    }
    inspect_prefix(frequencies);
    frequencies[255] += maximum - small_total;
    inspect_prefix(frequencies);
    if constexpr (std::numeric_limits<Counter>::digits > 32) {
        frequencies = {};
        frequencies[0] = std::numeric_limits<std::uint32_t>::max();
        frequencies[255] = 1;
        inspect_prefix(frequencies);
        SIRKIT_TEST_REQUIRE(!std::cmp_less_equal(
            std::uintmax_t(std::numeric_limits<std::uint32_t>::max()) + 1,
            std::numeric_limits<std::uint32_t>::max()));
    }
}

int main() {
    inspect_type<std::int8_t>(); inspect_type<std::uint8_t>();
    inspect_type<std::int16_t>(); inspect_type<std::uint16_t>();
    inspect_type<std::int32_t>(); inspect_type<std::uint32_t>();
    inspect_type<std::int64_t>(); inspect_type<std::uint64_t>();
    prefix_boundaries<std::uint32_t>(); prefix_boundaries<std::size_t>();
    std::printf("PASS radix counter checks=%ju input_cases=%ju kernel_calls=%ju prefix_cases=%ju\n",
                static_cast<std::uintmax_t>(checks), static_cast<std::uintmax_t>(input_cases),
                static_cast<std::uintmax_t>(kernel_calls), static_cast<std::uintmax_t>(prefix_cases));
}

