        if (values.size() <= std::numeric_limits<std::uint32_t>::max())
            reinsirk::detail::RadixSortDetail<T, std::uint32_t>::template sort<false>(values, buffer_, T{});
        else reinsirk::detail::RadixSortDetail<T>::template sort<false>(values, buffer_, T{});
    }
    void sort(std::vector<T>& values, T maximum) {
        if (values.size() <= std::numeric_limits<std::uint32_t>::max())
            reinsirk::detail::RadixSortDetail<T, std::uint32_t>::template sort<true>(values, buffer_, maximum);
        else reinsirk::detail::RadixSortDetail<T>::template sort<true>(values, buffer_, maximum);
    }
    void reserve(std::size_t count) { buffer_.reserve(count); }
    std::size_t capacity() const noexcept { return buffer_.capacity(); }
    void release() noexcept { std::vector<T>().swap(buffer_); }
};
#endif

