}
#endif

#ifndef SIRKIT_RADIX_SORT_ORDER_DEFINED
#define SIRKIT_RADIX_SORT_ORDER_DEFINED
template <reinsirk::detail::RadixInteger T> std::vector<std::size_t> RadixSortOrder(const std::vector<T>& values) {
    using Counter = typename reinsirk::detail::RadixSortDetail<T>::SmallCounter;
    if (std::cmp_less_equal(values.size(), std::numeric_limits<Counter>::max()))
        return reinsirk::detail::RadixSortDetail<T, Counter>::order(values);
    return reinsirk::detail::RadixSortDetail<T>::order(values);
}
#endif

