from pathlib import Path
import json,subprocess,fcntl,statistics,time,hashlib
r=Path('/home/reinsirk/Atcoder_Env');p=Path(__file__).parent;old=(p/'baseline.hpp').read_text();cur=(p/'final_counter.hpp').read_text();d={'builds':[],'cases':{},'text_identity64':[]};sha=lambda b:hashlib.sha256(b).hexdigest()
for mode,compiler in [('gcc',['/usr/bin/g++']),('gcc_native',['/usr/bin/g++','-march=native']),('clang',['clang++','--gcc-install-dir=/usr/lib/gcc/x86_64-linux-gnu/15'])]:
 for i in ['radix_sort','radix_sort_uint32']:
  base=(p/(i+'_baseline.cpp')).read_text();assert base.count(old)==1;h={}
  for v,body in [('old',old),('new',cur)]:
   src=p/(i+'_'+mode+'_'+v+'.cpp');src.write_text(base.replace(old,body));exe=src.with_suffix('');cmd=['taskset','-c','6',*compiler,'-std=c++23','-O2',str(src),'-o',str(exe)];subprocess.run(cmd,check=True,capture_output=True);d['builds'].append(cmd);tmp=p/'text';subprocess.run(['objcopy','--dump-section','.text='+str(tmp),str(exe)],check=True,capture_output=True);h[v]=sha(tmp.read_bytes())
  d['text_identity64'].append({'mode':mode,'id':i,'hashes':h,'identical':h['old']==h['new']})
 print('compiled',mode,flush=True)
with open('/tmp/sirkit_performance_cpu14.lock','a')as a,open('/tmp/atcoder_full_performance_20261018/benchmark.lock','a')as b:
 fcntl.flock(a,fcntl.LOCK_EX);fcntl.flock(b,fcntl.LOCK_EX)
 for mode in ['gcc','gcc_native','clang']:
  for i,kind in [(i,k)for i in ['radix_sort','radix_sort_uint32']for k in ['random','ascending','descending','equal','two','lowbyte','high_narrow']]:
   inp=Path('/tmp/sirkit_radix_ready_20261024/cases')/('large_'+kind+'.in');raw={'old':[],'new':[]}
   for rep in range(9):
    for v in (['old','new']if rep%2==0 else['new','old']):
     exe=p/(i+'_'+mode+'_'+v)
     with inp.open('rb')as inf:
      start=time.perf_counter();subprocess.run(['taskset','-c','14',str(exe)],stdin=inf,stdout=subprocess.DEVNULL,stderr=subprocess.PIPE,check=True);raw[v].append(time.perf_counter()-start)
   med={v:statistics.median(x)for v,x in raw.items()};ratio=med['new']/med['old'];d['cases'][mode+'/'+i+'/'+kind]={'raw_seconds':raw,'median_seconds':med,'new_over_old':ratio};print(mode,i,kind,ratio,flush=True)
