// SPDX-License-Identifier: CC0-1.0
#include HEADER
#include <chrono>
#include <cstdlib>
#include <iostream>
#include <random>
#include <string>
#include <vector>
template<class T>void bench(std::size_t n,int loops,int shape,int api){
 std::vector<T>input(n);std::mt19937_64 rng(925031);
 for(auto& v:input){auto x=rng();if(shape==1)x%=1000001;if(shape==2)x&=UINT64_C(0xff000000ff0000ff);if(shape==6)x%=256;v=static_cast<T>(x);}
 if(shape==3)std::sort(input.begin(),input.end());if(shape==4)std::sort(input.rbegin(),input.rend());if(shape==5)std::fill(input.begin(),input.end(),T{11});
 std::vector<T>a; a.reserve(n);RadixSortWorkspace<T>w;w.reserve(n);std::uint64_t checksum=0;
 const auto start=std::chrono::steady_clock::now();
 for(int k=0;k<loops;++k){if(api==2){auto order=RadixSortOrder(input);if(order.size()!=input.size())std::abort();if(n)checksum+=order[0]+order[n/2]+order.back();}
 else{a=input;if(api==0)RadixSort(a);else w.sort(a);if(!std::is_sorted(a.begin(),a.end()))std::abort();if(n)checksum+=static_cast<std::uint64_t>(a[0])+static_cast<std::uint64_t>(a[n/2])+static_cast<std::uint64_t>(a.back());}}
 std::cout<<std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-start).count()<<' '<<checksum<<'\n';
}
int main(int argc,char**argv){if(argc!=7)return 1;auto n=std::strtoull(argv[1],nullptr,10);int loops=std::atoi(argv[2]),shape=std::atoi(argv[3]),api=std::atoi(argv[4]),bits=std::atoi(argv[5]),sign=std::atoi(argv[6]);
 if(bits==64){if(sign)bench<std::int64_t>(n,loops,shape,api);else bench<std::uint64_t>(n,loops,shape,api);}else if(bits==32){if(sign)bench<std::int32_t>(n,loops,shape,api);else bench<std::uint32_t>(n,loops,shape,api);}else if(bits==16)bench<std::int16_t>(n,loops,shape,api);else bench<std::int8_t>(n,loops,shape,api);
}

