from pathlib import Path
import subprocess,json,fcntl,statistics,hashlib
p=Path(__file__).parent;res={'status':'INCOMPLETE','identity':[],'cases':{},'builds':[]};vs=['baseline','counter32','counter32_selective','counter32_selective_nativecmp'];configs={'gcc':(['/usr/bin/g++'],[]),'native':(['/usr/bin/g++','-march=native'],[]),'zen':(['/usr/bin/g++','-march=znver2'],[]),'clang':(['clang++','--gcc-install-dir=/usr/lib/gcc/x86_64-linux-gnu/15'],[]),'gcc_scalar':(['/usr/bin/g++'],['-DSIRKIT_DISABLE_SIMD']),'clang_scalar':(['clang++','--gcc-install-dir=/usr/lib/gcc/x86_64-linux-gnu/15'],['-DSIRKIT_DISABLE_SIMD'])}
# Whole all-typebench mayshift functionlayout whenClang32changes; compareindividualtypebenchtextinstead.
b=(p/'bench.cpp').read_text();a=b.index('int main(int argc,char**argv)');(p/'bench64.cpp').write_text(b[:a]+'''int main(int argc,char**argv){if(argc!=7)return 1;bench<std::int64_t>(std::strtoull(argv[1],nullptr,10),std::atoi(argv[2]),std::atoi(argv[3]),std::atoi(argv[4]));}\n''');(p/'bench32.cpp').write_text(b[:a]+'''int main(int argc,char**argv){if(argc!=7)return 1;if(std::atoi(argv[6]))bench<std::int32_t>(std::strtoull(argv[1],nullptr,10),std::atoi(argv[2]),std::atoi(argv[3]),std::atoi(argv[4]));else bench<std::uint32_t>(std::strtoull(argv[1],nullptr,10),std::atoi(argv[2]),std::atoi(argv[3]),std::atoi(argv[4]));}\n''')
for mode,(cc,fl)in configs.items():
 for v in vs:
  for bits in ([32,64]if mode.startswith('clang')else[32]):
   src=p/('bench'+str(bits)+'.cpp');exe=p/(mode+'_'+v+'_'+str(bits));cmd=['taskset','-c','6',*cc,'-std=c++23','-O2','-DSKIP_RUNTIME_CHECKS',*fl,'-DHEADER="'+str(p/(v+'.hpp'))+'"',str(src),'-o',str(exe)];subprocess.run(cmd,check=True,capture_output=True);res['builds'].append(cmd)
 for bits in ([32,64]if mode.startswith('clang')else[32]):
  hs={}
  for v in vs:
   out=p/'identity.text';subprocess.run(['objcopy','--dump-section','.text='+str(out),str(p/(mode+'_'+v+'_'+str(bits)))],check=True,capture_output=True);hs[v]=hashlib.sha256(out.read_bytes()).hexdigest()
  if mode.startswith('clang')and bits==64:print('clang64identity',hs['counter32_selective']==hs['counter32'],hs['counter32_selective_nativecmp']==hs['counter32'],flush=True)
  if not mode.startswith('clang'):assert hs['counter32_selective']==hs['counter32'],(mode,bits,hs)
  res['identity'].append({'mode':mode,'bits':bits,'text_sha256':hs});print(mode,bits,'identity',hs,flush=True)
with open('/tmp/sirkit_performance_cpu16.lock','a')as lock:
 fcntl.flock(lock,fcntl.LOCK_EX)
 for mode in ['clang','clang_scalar']:
  res['cases'][mode]={}
  for n,loops,shape,api,bits,sign in [(32,10000,0,0,32,0),(4096,64,0,0,32,0),*[(500000,8,s,a,32,sign)for s in [0,1,5]for a in [0,1,2]for sign in [0,1]],*[(200000,16,s,a,64,1)for s in [0,1,3]for a in [0,1,2]]]:
   raw={v:[]for v in vs};checksum=None;args=(n,loops,shape,api,bits,sign)
   for rep in range(9):
    for v in vs[rep%4:]+vs[:rep%4]:
     out=subprocess.check_output(['taskset','-c','16',str(p/(mode+'_'+v+'_'+str(bits))),*map(str,args)]).decode().split();raw[v].append(float(out[0]));checksum=out[1]if checksum is None else checksum;assert checksum==out[1]
   med={v:statistics.median(x)for v,x in raw.items()};rat={v:x/med['baseline']for v,x in med.items()};res['cases'][mode]['/'.join(map(str,args))]={'raw_ms':raw,'median_ms':med,'ratios':rat};print(mode,args,{k:round(v,3)for k,v in rat.items()},flush=True)
res['status']='PASS';(p/'selective_results.json').write_text(json.dumps(res,indent=2)+'\n')

